"""Routes for Captures, generated by Dryv; the engine implements StagingCapturesService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends, Path, Query, Request

from mzizi_engine.api.schemas.api.staging.models.capture_list import CaptureList
from mzizi_engine.api.schemas.mongo.staging.models.capture import Capture

__all__ = ["StagingCapturesService", "build_staging_captures_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class StagingCapturesService(ABC):
    """What Captures needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_capture(self, *, capture_id: UUID) -> Capture:
        """One capture: where it came from, its hash and where the raw bytes are stored."""

    @abstractmethod
    async def list_captures(self, *, source_id: UUID | None, limit: int | None) -> CaptureList:
        """Recent captures, newest first, optionally for one source."""


def build_staging_captures_router(service: StagingCapturesService, guard: Guard | None = None) -> APIRouter:
    """Routes for Captures, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Captures"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/captures/{captureId}",
        response_model=Capture,
        status_code=200,
        summary="One capture: where it came from, its hash and where the raw bytes are stored.",
    )
    async def get_capture(
        capture_id: Annotated[UUID, Path(alias="captureId")],
    ) -> Capture:
        return await service.get_capture(capture_id=capture_id)

    @router.get(
        "/v1/captures",
        response_model=CaptureList,
        status_code=200,
        summary="Recent captures, newest first, optionally for one source.",
    )
    async def list_captures(
        source_id: Annotated[UUID | None, Query(alias="sourceId")] = None,
        limit: Annotated[int | None, Query(alias="limit")] = None,
    ) -> CaptureList:
        return await service.list_captures(source_id=source_id, limit=limit)

    return router
